const express = require('express');
const { Pool } = require('pg');
const path = require('path');
const crypto = require('crypto');

// Foto de fundo da tela inicial do convite (embutida pra não precisar hospedar arquivo).
const FOTO_INTRO_B64 = '';

const app = express();
const PORT = process.env.PORT || 3000;

// Data limite para confirmação (formato AAAA-MM-DD).
// Ordem de prioridade: (1) banco → (2) env DATA_LIMITE → (3) constante padrão
const DATA_LIMITE_PADRAO = process.env.DATA_LIMITE || '2027-01-03';
const DATA_FESTA         = process.env.DATA_FESTA  || '2027-01-10';

// Cache em memória (evita hit no banco a cada rowToGuest). Atualizado quando alguém salva via PUT.
let _cacheDataLimite = null;
let _cacheValorBuffet = null;
const VALOR_BUFFET_PADRAO = parseFloat(process.env.VALOR_BUFFET || '77.97');

async function getValorBuffet() {
  if (_cacheValorBuffet !== null) return _cacheValorBuffet;
  try {
    const { rows } = await pool.query("SELECT valor FROM dados WHERE chave = 'valorBuffet'");
    if (rows.length) {
      const v = JSON.parse(rows[0].valor);
      const n = typeof v === 'number' ? v : parseFloat(v);
      if (!isNaN(n) && n >= 0) { _cacheValorBuffet = n; return n; }
    }
  } catch {}
  _cacheValorBuffet = VALOR_BUFFET_PADRAO;
  return _cacheValorBuffet;
}

async function getDataLimite() {
  if (_cacheDataLimite) return _cacheDataLimite;
  try {
    const { rows } = await pool.query("SELECT valor FROM dados WHERE chave = 'dataLimite'");
    if (rows.length) {
      const v = JSON.parse(rows[0].valor);
      if (v && typeof v === 'string') { _cacheDataLimite = v; return v; }
    }
  } catch {}
  _cacheDataLimite = DATA_LIMITE_PADRAO;
  return _cacheDataLimite;
}
// Versão síncrona pra usar dentro de rowToGuest (retorna do cache ou padrão)
function getDataLimiteSync() {
  return _cacheDataLimite || DATA_LIMITE_PADRAO;
}

// ── Database setup (PostgreSQL) ──────────────────────────────
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false },
});

async function initDB() {
  // Create tables
  await pool.query(`
    CREATE TABLE IF NOT EXISTS convidados (
      id SERIAL PRIMARY KEY,
      nome TEXT NOT NULL,
      grupo TEXT DEFAULT 'Amigos',
      confirmado INTEGER DEFAULT NULL,
      adultos INTEGER DEFAULT 1,
      criancas INTEGER DEFAULT 0,
      telefone TEXT DEFAULT '',
      "conviteEnviado" INTEGER DEFAULT 0,
      token TEXT UNIQUE
    );
    CREATE TABLE IF NOT EXISTS dados (
      chave TEXT PRIMARY KEY,
      valor TEXT NOT NULL
    );
  `);
  // Add new columns if they don't exist yet (migration)
  const migrations = [
    `ALTER TABLE convidados ADD COLUMN IF NOT EXISTS "idadeCrianca" TEXT DEFAULT ''`,
    `ALTER TABLE convidados ADD COLUMN IF NOT EXISTS "nomes" TEXT DEFAULT ''`,
    `ALTER TABLE convidados ADD COLUMN IF NOT EXISTS "pessoasConfirmadas" TEXT DEFAULT ''`,
    `ALTER TABLE convidados ADD COLUMN IF NOT EXISTS "dataConfirmacao" TIMESTAMPTZ`,
    `ALTER TABLE convidados ADD COLUMN IF NOT EXISTS "idadesPorNome" TEXT DEFAULT ''`,
  ];
  for (const sql of migrations) {
    await pool.query(sql).catch(()=>{});
  }
  console.log('Banco pronto!');
}
initDB()
  .then(() => getDataLimite())
  .catch(err => console.error('Erro ao iniciar banco:', err));

// ── Helpers ──────────────────────────────────────────────────
function gerarToken() { return crypto.randomBytes(8).toString('hex'); }

// "Yasmin, Arthur (6 anos) e Dayanne" -> ["Yasmin", "Arthur (6 anos)", "Dayanne"]
function parseNomes(str) {
  if (!str || !String(str).trim()) return [];
  return String(str)
    .split(/,|\s+e\s+/i)
    .map(s => s.trim())
    .filter(Boolean);
}

function parsePessoasConfirmadas(raw) {
  if (!raw) return [];
  try { const arr = JSON.parse(raw); return Array.isArray(arr) ? arr : []; }
  catch { return []; }
}

// Objeto {nome: idade} parseado do JSON
function parseIdadesPorNome(raw) {
  if (!raw) return {};
  try { const o = JSON.parse(raw); return (o && typeof o === 'object' && !Array.isArray(o)) ? o : {}; }
  catch { return {}; }
}

// Classifica crianças por idade a partir do campo idadeCrianca (texto livre) + total de crianças.
// Regras: 0-4 = isento, 5-9 = meia, 10+ = integral. Sem idade = indefinida (cobrada integral).
function classificarIdades(idadeCriancaStr, numCriancas) {
  const idades = String(idadeCriancaStr || '').match(/\d+/g)?.map(Number) || [];
  let isentas = 0, meias = 0, integraisCrianca = 0;
  for (const idade of idades.slice(0, numCriancas)) {
    if (idade <= 4) isentas++;
    else if (idade <= 9) meias++;
    else integraisCrianca++;
  }
  const indefinidas = Math.max(0, numCriancas - idades.length);
  return { isentas, meias, integraisCrianca, indefinidas, idades };
}

// Calcula valor a pagar do grupo. Prioriza idadesPorNome (por pessoa) quando disponível.
// Fallback: parse de idadeCrianca + contador criancas (modo legado).
function calcularValor(row, valorIntegral) {
  const idadesPorNome = (row.idadesPorNome && typeof row.idadesPorNome === 'object' && !Array.isArray(row.idadesPorNome))
    ? row.idadesPorNome
    : parseIdadesPorNome(row.idadesPorNome);
  const temIdadesPorNome = Object.keys(idadesPorNome).length > 0;

  if (temIdadesPorNome) {
    // Lista: confirmadas se houver, senão todos os nomes cadastrados
    const confirmadasRaw = Array.isArray(row.pessoasConfirmadas) ? row.pessoasConfirmadas : parsePessoasConfirmadas(row.pessoasConfirmadas);
    const lista = confirmadasRaw.length ? confirmadasRaw : parseNomes(row.nomes);
    let qtdIntegral = 0, qtdMeia = 0, qtdIsenta = 0;
    const detalhes = [];
    for (const nome of lista) {
      const raw = idadesPorNome[nome];
      const idade = (raw === '' || raw === null || raw === undefined) ? null : Number(raw);
      let categoria;
      if (idade === null || isNaN(idade)) { qtdIntegral++; categoria = 'integral'; }
      else if (idade <= 4)                { qtdIsenta++;   categoria = 'isenta';  }
      else if (idade <= 9)                { qtdMeia++;     categoria = 'meia';    }
      else                                { qtdIntegral++; categoria = 'integral';}
      detalhes.push({ pessoa: nome, idade, categoria });
    }
    const total = qtdIntegral * valorIntegral + qtdMeia * (valorIntegral / 2);
    return { qtdIntegral, qtdMeia, qtdIsenta, qtdIndefinida: 0, total, detalhes, usouIdadesPorNome: true };
  }

  // Modo legado
  const c = classificarIdades(row.idadeCrianca, row.criancas);
  const qtdIntegral = row.adultos + c.integraisCrianca + c.indefinidas;
  const qtdMeia = c.meias;
  const qtdIsenta = c.isentas;
  const total = qtdIntegral * valorIntegral + qtdMeia * (valorIntegral / 2);
  return { qtdIntegral, qtdMeia, qtdIsenta, qtdIndefinida: c.indefinidas, total, detalhes: null, usouIdadesPorNome: false };
}

// true se a confirmação (se houver) foi feita depois da data limite
function foiAposPrazo(dataConfirmacao) {
  if (!dataConfirmacao) return false;
  const limite = new Date(getDataLimiteSync() + 'T23:59:59');
  return new Date(dataConfirmacao) > limite;
}

// true se HOJE já passou da data limite (usado pra bloquear novas edições)
async function prazoEncerrado() {
  const dataLimite = await getDataLimite();
  const limite = new Date(dataLimite + 'T23:59:59');
  return new Date() > limite;
}

function rowToGuest(row) {
  return {
    id: row.id,
    nome: row.nome,
    grupo: row.grupo,
    confirmado: row.confirmado === null ? null : Number(row.confirmado) === 1,
    adultos: row.adultos,
    criancas: row.criancas,
    telefone: row.telefone || '',
    conviteEnviado: Number(row.conviteEnviado) === 1,
    idadeCrianca: row.idadeCrianca || '',
    nomes: row.nomes || '',
    pessoasConfirmadas: parsePessoasConfirmadas(row.pessoasConfirmadas),
    dataConfirmacao: row.dataConfirmacao || null,
    aposPrazo: foiAposPrazo(row.dataConfirmacao),
    idadesPorNome: parseIdadesPorNome(row.idadesPorNome),
    token: row.token,
  };
}

// ── Middleware ───────────────────────────────────────────────
// strict:false permite que primitivos JSON (strings, números, booleans)
// venham no body — sem isso, apiPut(path, "2027-01-05") não persiste.
app.use(express.json({ strict: false }));
app.use(express.urlencoded({ extended: true }));
app.use(express.static(path.join(__dirname)));
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Headers', 'Content-Type');
  res.header('Access-Control-Allow-Methods', 'GET,POST,PUT,DELETE,OPTIONS');
  if (req.method === 'OPTIONS') return res.sendStatus(200);
  next();
});

// ── API: Convidados ──────────────────────────────────────────
app.get('/api/convidados', async (req, res) => {
  try {
    const { rows } = await pool.query('SELECT * FROM convidados ORDER BY id');
    res.json(rows.map(rowToGuest));
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/convidados', async (req, res) => {
  try {
    const { nome, grupo = 'Amigos', adultos = 1, criancas = 0, telefone = '', idadeCrianca = '', nomes = '' } = req.body;
    if (!nome) return res.status(400).json({ error: 'Nome obrigatorio' });
    const token = gerarToken();
    const { rows } = await pool.query(
      'INSERT INTO convidados (nome, grupo, adultos, criancas, telefone, "idadeCrianca", "nomes", token) VALUES ($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *',
      [nome, grupo, adultos, criancas, telefone, idadeCrianca||'', nomes||'', token]
    );
    res.json(rowToGuest(rows[0]));
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.put('/api/convidados/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const allowed = ['nome','grupo','adultos','criancas','telefone','confirmado','conviteEnviado','idadeCrianca','nomes','pessoasConfirmadas','idadesPorNome'];
    const updates = []; const values = []; let i = 1;
    allowed.forEach(f => {
      if (f in req.body) {
        updates.push(`"${f}" = $${i++}`);
        let val = req.body[f];
        if (f === 'confirmado') val = val === null ? null : val ? 1 : 0;
        if (f === 'conviteEnviado') val = val ? 1 : 0;
        if (f === 'pessoasConfirmadas') val = Array.isArray(val) ? JSON.stringify(val) : (val || '');
        if (f === 'idadesPorNome') val = (val && typeof val === 'object' && !Array.isArray(val)) ? JSON.stringify(val) : (val || '');
        values.push(val);
      }
    });
    if (!updates.length) return res.status(400).json({ error: 'Nada para atualizar' });
    values.push(id);
    const { rows } = await pool.query(
      `UPDATE convidados SET ${updates.join(', ')} WHERE id = $${i} RETURNING *`, values
    );
    res.json(rowToGuest(rows[0]));
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.delete('/api/convidados/:id', async (req, res) => {
  try {
    await pool.query('DELETE FROM convidados WHERE id = $1', [req.params.id]);
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── API: Dados extras ────────────────────────────────────────
app.get('/api/dados/:chave', async (req, res) => {
  try {
    const { rows } = await pool.query('SELECT valor FROM dados WHERE chave = $1', [req.params.chave]);
    res.json(rows.length ? JSON.parse(rows[0].valor) : null);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.put('/api/dados/:chave', async (req, res) => {
  try {
    await pool.query(
      'INSERT INTO dados (chave,valor) VALUES ($1,$2) ON CONFLICT (chave) DO UPDATE SET valor=EXCLUDED.valor',
      [req.params.chave, JSON.stringify(req.body)]
    );
    // Invalida cache se a chave editada é a data limite
    if (req.params.chave === 'dataLimite')  _cacheDataLimite  = null;
    if (req.params.chave === 'valorBuffet') _cacheValorBuffet = null;
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Configuração pública (data da festa e prazo) ─────────────
app.get('/api/config', async (req, res) => {
  const [dataLimite, valorBuffet] = await Promise.all([getDataLimite(), getValorBuffet()]);
  res.json({ dataLimite, dataFesta: DATA_FESTA, valorBuffet });
});

// ── Confirmação pública ──────────────────────────────────────
app.get('/confirmar/:token', async (req, res) => {
  try {
    const { rows } = await pool.query('SELECT * FROM convidados WHERE token = $1', [req.params.token]);
    if (!rows.length) return res.send(paginaErro('Link inválido ou expirado.'));
    res.send(await paginaConfirmacao(rows[0]));
  } catch (e) { res.send(paginaErro('Erro interno.')); }
});

app.post('/confirmar/:token', async (req, res) => {
  try {
    // Trava dura: depois do prazo, ninguém confirma/altera pelo link público
    if (await prazoEncerrado()) {
      const dataLimite = await getDataLimite();
      const dataFmt = new Date(dataLimite + 'T00:00:00').toLocaleDateString('pt-BR', { day:'2-digit', month:'long', year:'numeric' });
      return res.status(403).send(paginaErro(`Prazo de confirmação encerrado (${dataFmt}). Entre em contato com o anfitrião para qualquer ajuste.`));
    }
    const { resposta } = req.body;
    const { rows } = await pool.query('SELECT * FROM convidados WHERE token = $1', [req.params.token]);
    if (!rows.length) return res.status(404).send(paginaErro('Token inválido'));
    const guest = rows[0];
    const confirmado = resposta === 'sim' ? 1 : 0;

    // Coletar nomes marcados. O form envia um campo "pessoas" pra cada checkbox marcado
    // (express.urlencoded coleta em array quando repetido).
    let pessoasArr = [];
    if (confirmado === 1) {
      const p = req.body.pessoas;
      if (Array.isArray(p)) pessoasArr = p.filter(Boolean);
      else if (typeof p === 'string' && p) pessoasArr = [p];
      else {
        // Fallback: se o convidado não tem nomes cadastrados, assume o próprio nome dele
        const listaOriginal = parseNomes(guest.nomes);
        pessoasArr = listaOriginal.length ? listaOriginal : [guest.nome];
      }
    }

    await pool.query(
      `UPDATE convidados
         SET confirmado = $1,
             "conviteEnviado" = 1,
             "pessoasConfirmadas" = $2,
             "dataConfirmacao" = NOW()
       WHERE token = $3`,
      [confirmado, JSON.stringify(pessoasArr), req.params.token]
    );
    res.send(paginaObrigado(guest.nome, resposta === 'sim', pessoasArr));
  } catch (e) { res.send(paginaErro('Erro ao salvar resposta.')); }
});

// ── Páginas HTML ─────────────────────────────────────────────
